export type PanelId = "map" | "metrics" | "notes";
export type PanelSnapshot = Readonly<Record<PanelId, boolean>>;

type Listener = (snapshot: PanelSnapshot) => void;

export class PanelStateStore {
  private readonly state: Record<PanelId, boolean>;
  private readonly listeners: Listener[] = [];

  constructor(initial: Partial<Record<PanelId, boolean>> = {}) {
    for (const id of ["map", "metrics", "notes"] as const) {
      if (Object.prototype.hasOwnProperty.call(initial, id) && typeof initial[id] !== "boolean") {
        throw new TypeError(`Initial value for ${id} must be boolean`);
      }
    }
    this.state = {
      map: initial.map ?? false,
      metrics: initial.metrics ?? false,
      notes: initial.notes ?? false
    };
  }

  getSnapshot(): PanelSnapshot {
    return Object.freeze({ ...this.state });
  }

  setVisible(id: PanelId, visible: boolean): void {
    this.state[id] = visible;
    this.notify();
  }

  toggle(id: PanelId): void {
    this.state[id] = !this.state[id];
    this.notify();
  }

  subscribe(listener: Listener): () => void {
    this.listeners.push(listener);
    let active = true;
    return () => {
      if (!active) return;
      active = false;
      const index = this.listeners.indexOf(listener);
      if (index >= 0) this.listeners.splice(index, 1);
    };
  }

  private notify(): void {
    for (const listener of [...this.listeners]) listener(this.getSnapshot());
  }
}
